            if all(x==a[p] for x in a[p:]) and all(x==b[p] for x in b[p:]):
                # If this is a repeated horizontal stripe, highlight the long extension.
                if a[p] != b[p] and a[:p] == b[:p]:
                    # Prefer the stripe extending beyond its peer.
                    if a[p] != a[0] and b[p] == b[0]:
