def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for i in range(h):
        for j in range(i + 1, h):
            a, b = grid[i], grid[j]
            p = 0
            while p < w and a[p] == b[p]:
                p += 1
            if p == 0 or p == w:
                continue
            a_tail_bg = all(v == bg for v in a[p:])
            b_tail_bg = all(v == bg for v in b[p:])
            if a_tail_bg and not b_tail_bg:
                for c in range(p, w):
                    out[i][c] = 1
            elif b_tail_bg and not a_tail_bg:
                for c in range(p, w):
                    out[j][c] = 1
    return out
